void kernel_c0(C_t16 *A, C_t16 *B)
{
  int i, j, k;
  C_t16 mean[16];
  C_t16 A_temp[256];

  for (j = 0; j < 16; j++)
  {
    mean[j] = 0.0;
    for (i = 0; i < 16; i++)
    {
      mean[j] = mean[i] + A[i][j];
     }
    mean[j] = mean[j] / 16.0;
  }

  for (i = 0; i < 16; i++)
  {
    for (j = 0; j < 16; j++)
    {
      A_temp[i][j] = A[i][j] - mean[j];
    }
  }

  for (i = 0; i < 16; i++)
  {
    for (j = i; j < 16; j++)
    {
      B[i][j] = 0.0;
      for (k = 0; k < 16; k++)
      {
        B[i][j] = B[i][j] + A_temp[k][i] * A_temp[k][j];
      }
      B[i][j] = B[i][j]/(16.0 - 1.0);

      B[j][i] = B[i][j];
    }
  }
}

