#include <limits>

// Arbitrary-precision signed integer
template<int W>
class ap_int {
public:
    // Use largest standard type that fits
    using storage_type = typename std::conditional<
        (W <= 8), int8_t,
        typename std::conditional<
            (W <= 16), int16_t,
            typename std::conditional<
                (W <= 32), int32_t,
                int64_t
            >::type
        >::type
    >::type;

